primaryQuery:
run: order_items -> {
  where: year(created_at) = 2022
  aggregate:
    units_sold is count() { where: status != 'Cancelled' }
    all_2022_lines is count()
    cancelled_2022_lines is count() { where: status = 'Cancelled' }
}

verifyQuery:
run: order_items -> {
  where: created_at >= @2022-01-01 and created_at < @2023-01-01
  group_by: status
  aggregate: n is count()
} -> {
  aggregate:
    all_2022_lines is n.sum()
    cancelled_2022_lines is n.sum() { where: status = 'Cancelled' }
} -> {
  select:
    units_sold is all_2022_lines - cancelled_2022_lines
    all_2022_lines
    cancelled_2022_lines
}
